using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class PrivateInspectionTests
{
    static readonly EntityId Person=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Start(bool modern=true,bool willing=true){var p=NewGameWorldTests.Officer(role:StartTemplate.Ronin,site:"site:kofu");var setup=NewGameSetup.Preview(NewGameWorld.Scenario(HistoricalStartCatalog.Current),new([p],[]));Assert.True(setup.IsEligible());var w=NewGameWorld.Create(setup.World!,[p],p.Id,historicalCatalog:HistoricalStartCatalog.Current,npcRoutinePolicy:NewGameNpcRoutine.Policy,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:modern?PersonalCompanions.PrivateInspectionPolicy:PersonalCompanions.Policy,informationPolicy:PrivateInformation.Policy);if(!willing)w.Characters=w.Characters.Select(c=>c.Id==Person?c with{WillObey=false}:c).ToArray();return new(w);}
    static void At(WorldSession s,long at)=>PersonalCompanionTests.Advance(s,at);
    static void Contact(WorldSession s){At(s,8);var q=new EntityId("request:commission-contact");void Do(InformationAction a,string id,EntityId? quote=null){var r=s.ContactForInformation(new(new(id),Person,a,quote),s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}Do(InformationAction.Ask,q.Value);Do(InformationAction.Accept,"request:commission-info-accept",q);At(s,9);var m=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind==PrivateInformation.Kind);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(m.Id),s.Revision).Code);Do(InformationAction.Pay,"request:commission-info-pay",q);}
    static CommandResult Ask(WorldSession s,long money=20,string? id=null)=>s.ManageCompanion(new(new(id??"request:private-inspect/"+s.Revision),Person,CompanionAction.PrivateInspect,money),s.PlayerControl,s.Revision);
    [Fact]public void ForeignRetainerWorksWithoutRecruitmentAndOnlyChargesOnce(){var s=Start();Contact(s);var b=s.DiagnosticSnapshot();var r=Ask(s,id:"request:one-job");Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);Assert.Equal(ResultCode.AlreadyAccepted,Ask(s,id:"request:one-job").Code);var w=s.DiagnosticSnapshot();Assert.Equal(960,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(1040,NewGameWork.Balance(w,Person));Assert.Equal(ContractJson.Write(b.Memberships),ContractJson.Write(w.Memberships));Assert.Equal(ContractJson.Write(b.ServiceBonds),ContractJson.Write(w.ServiceBonds));Assert.Equal(ContractJson.Write(b.Grants),ContractJson.Write(w.Grants));Assert.Empty(w.Units);var c=s.CompanionView().Single(c=>c.Person==Person);Assert.False(c.Active);Assert.Equal(0,c.Owed);At(s,86410);Assert.Equal(0,s.CompanionView().Single(c=>c.Person==Person).Owed);Assert.Equal(960,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact]public void PriorPaidContactIsRequired(){var s=Start();At(s,8);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Ask(s).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void BusyOrUnwillingPersonRefusesWithoutCharge(){var s=Start();Contact(s);var refusal=s.DiagnosticSnapshot();refusal.Characters=refusal.Characters.Select(c=>c.Id==Person?c with{WillObey=false}:c).ToArray();s=new WorldSession(refusal);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Ask(s).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));s=Start();Contact(s);Assert.Equal(ResultCode.Accepted,Ask(s).Code);b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Ask(s).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(19)][InlineData(21)][InlineData(-1)]public void FeeCannotBeChanged(long amount){var s=Start();Contact(s);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Ask(s,amount).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void ForeignRetainerStillCannotBeHiredOrOrderedToFollow(){var s=Start();Contact(s);Ask(s);At(s,17);foreach(var a in new[]{CompanionAction.Agree,CompanionAction.TravelTogether,CompanionAction.Inspect}){var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageCompanion(new(new("request:no-enlist/"+a),Person,a,a==CompanionAction.Agree?20:0,a==CompanionAction.TravelTogether?"fork":null),s.PlayerControl,s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}}
    [Fact]public void ExactCompletedJobProducesFreshOwnObservationAndSealedLocalReply(){var s=Start();Contact(s);long old=s.Seconds;var known=ContractJson.Write(s.GetActorView(s.PlayerControl).Evidence.Where(e=>e.Claim.StartsWith("route-")));Assert.Equal(ResultCode.Accepted,Ask(s).Code);var q=s.DiagnosticSnapshot().Companions!.Orders.Single();Assert.Equal(Person,q.Task!.Actor);Assert.Equal(Person,q.Task.Executor);At(s,old+2);var w=s.DiagnosticSnapshot();Assert.DoesNotContain(w.Evidence,e=>e.Subject==w.Tasks.Single(t=>t.RequestId==q.Task.RequestId).Id&&e.Claim.StartsWith("route-"));At(s,old+8);w=s.DiagnosticSnapshot();var t=w.Tasks.Single(t=>t.RequestId==q.Task.RequestId);Assert.Equal(ExecutionPhase.Completed,t.Execution);Assert.Contains(w.Evidence,e=>e.Observer==Person&&e.Subject==t.Id&&e.ObservedAt>old);Assert.Equal(known,ContractJson.Write(s.GetActorView(s.PlayerControl).Evidence.Where(e=>e.Claim.StartsWith("route-"))));var report=Assert.Single(w.Companions!.Reports);Assert.DoesNotContain(w.Messaging.Knowledge,k=>k.MessageId==report.Message&&k.CharacterId==s.PlayerControl.Value);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(report.Message),s.Revision).Code);Assert.Equal(known,ContractJson.Write(s.GetActorView(s.PlayerControl).Evidence.Where(e=>e.Claim.StartsWith("route-"))));Assert.False(s.CompanionView().Single(c=>c.Person==Person).Active);}
    [Fact]public void DuringWorkAndAfterOpeningRealGenerationRecoveryAndFutureAreIdentical(){var s=Start();Contact(s);Ask(s);At(s,s.Seconds+2);var loaded=Recover(s,"working");Export(s,loaded,"private-inspection-working");At(s,20);At(loaded,20);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(loaded.DiagnosticSnapshot()));var m=s.DiagnosticSnapshot().Companions!.Reports.Single().Message;Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(m),s.Revision).Code);loaded=Recover(s,"opened");Export(s,loaded,"private-inspection-opened");At(s,86410);At(loaded,86410);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(loaded.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.CompanionView()),ContractJson.Write(loaded.CompanionView()));}
    [Fact]public void OldCompanionPolicyRejectsNewActionAndKeepsWorldBytes(){var s=Start(false);Contact(s);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Ask(s).Code);Assert.Equal(bytes,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));}
    [Fact]public void ForgedFeeAndMissingTaskCannotLoad(){var s=Start();Contact(s);Ask(s);var w=s.DiagnosticSnapshot();var q=w.Companions!.Orders.Single();w.Companions=w.Companions with{Orders=[q with{Input=q.Input with{Amount=19}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Companions=w.Companions! with{Orders=[q with{Task=null}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    static WorldSession Recover(WorldSession s,string slot){s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"private-inspection-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,slot,w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare(slot),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));return host.Current;}
    static void Export(WorldSession a,WorldSession b,string name){var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(string.IsNullOrWhiteSpace(dir))return;Directory.CreateDirectory(dir);foreach(var x in new[]{(s:a,t:"before"),(s:b,t:"restored")})File.WriteAllBytes(Path.Combine(dir,name+"."+x.t+".json"),ContractJson.Write(x.s.DiagnosticSnapshot()));}
}
